  selectedJobcardId.value = jobcard.card
  getJobcardSummary(jobcard.card)
}

const totalCostSiteFuel = ref(0)
const totalCostHeadOfficeFuel = ref(0)

const getAssetFuelStatement = async () => {
  loading.value = true

  try {
    const response = await axiosInstance.get(
      `asset-fuel-statement?asset_id=${route.params.asset_id}`
    )

    const siteFuel = response.data.site_fuel || []
    const headOfficeFuel = response.data.head_office_fuel || []


    totalCostSiteFuel.value = 0
    totalCostHeadOfficeFuel.value = 0

    fuelStatement.value.site_fuel = siteFuel.map((item, index) => {
      const appliedRate =
        item.rate && parseFloat(item.rate) > 0
          ? parseFloat(item.rate)
          : fuel_rate

      const quantity = parseFloat(item.quantity) || 0
      const cost = quantity * appliedRate

      totalCostSiteFuel.value += cost

      return {
        Sno: index + 1,
        date: formatDate(item.date),
        task: item.task ?? '---',
        quantity: quantity + ' Ltr',
        balance : item.balance ?? 0 + ' Ltr',
        issuer:item.issuer?.name,
        rate: formatNumber(appliedRate),
        cost: formatNumber(cost),
        action:item.action,
        expected_ratio : item.ratio + ' ' + response.data.asset.consuption_type,
        initial_reading: item.initial_reading,
        final_reading: item.final_reading,
        work_target: item.work_target,
        work_covered:item.work_covered,
        unit:item.unit,
        remark:item.remark,
        description:item.description,
      }
    })

    fuelStatement.value.head_office_fuel = headOfficeFuel.map((item, index) => {
      const appliedRate =
        item.rate && parseFloat(item.rate) > 0
          ? parseFloat(item.rate)
          : fuel_rate

      const quantity = parseFloat(item.quantity) || 0
      const cost = quantity * appliedRate

      totalCostHeadOfficeFuel.value += cost

      return {
        Sno: index + 1,
        date: formatDate(item.created_at),
        task: item.task ?? '---',
        quantity: quantity,
        issuer:item.user?.name,
        rate: formatNumber(appliedRate),
        cost: formatNumber(cost),
        remark:item.remark,
        odometer : item.initial_reading,
        final_reading : item.final_reading ?? '---',
        lpo : item?.grn?.order?.id ?? '---' ,
        grn : item?.grn?.id ?? '---' ,
        ratio : profile?.value?.asset?.consuption_type === 'Litre/hr'  ? (item?.quantity /(item.final_reading - item.initial_reading)).toFixed(2) : ((item.final_reading - item.initial_reading)/item?.quantity).toFixed(2)  
      }
    })

  } catch (error) {
    console.log(error)
    showError(error.message)
  } finally {
    loading.value = false
  }
}
