      ...item,
      Sno: index + 1,
      jobcard: item.job_card_id,
      date: item.date,
      defect: item.description,
      reported_by: item.reported_by,
    }))
    totalDefects.value = formatNumber(response.data.total_cost)
  } catch (error) {
    console.log(error)
    showError(error.message)
  } finally {
    loading.value = false
  }
}




    onMounted(() => {
         getProfile()
    });


</script>

